import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import { StateBanner } from '@kerfjs/ui/state-banner';

type State = { status: 'loading' } | { status: 'empty' } | { status: 'ready' | 'refreshing'; items: readonly { id: string; title: string }[]; error?: string } | { status: 'error'; error: string };
export function renderListWorkspace(target: HTMLElement, state: State, retry: () => void) {
  target.replaceChildren();
  if (state.status === 'loading') return LoadingSpinner({ target, label: 'Loading items' });
  if (state.status === 'empty') return EmptyState({ target, title: 'No items yet', description: 'Create an item to begin.' });
  if (state.status === 'error') return StateBanner({ target, status: 'error', title: 'Could not load items', description: state.error, action: { label: 'Try again', onSelect: retry } });
  if (state.status === 'refreshing') StateBanner({ target, status: 'info', title: 'Refreshing items', description: 'Showing the last available results.' });
  if (state.error) StateBanner({ target, status: 'error', title: 'Refresh failed', description: state.error, action: { label: 'Try again', onSelect: retry } });
  const list = document.createElement('ul');
  list.setAttribute('aria-label', 'Items');
  for (const item of state.items) { const row = document.createElement('li'); row.textContent = item.title; list.append(row); }
  target.append(list);
}
